GRADES={'clinical_supported':'Systematic review and/or EMA well-established use supports a specific indication (efficacy still often modest; product-specific).','clinical_mixed':'Clinical trials exist but a systematic review judged them inconsistent, low quality or insufficient.','traditional_only':'Accepted by EMA HMPC on the basis of long-standing (traditional) use only; efficacy not shown in adequate trials.','monograph_area_only':'EMA lists an adopted EU monograph in this therapeutic area, but the public page had no summary stating whether use is traditional or well-established; treat as at most traditional until the monograph PDF is read.','not_endorsed':'EMA HMPC issued a public statement instead of a monograph (no use endorsed).','no_known_benefit':'No EMA HMPC monograph and no Cochrane review located for this plant in our search; no evidence-based medicinal use known to this pack.'}
def U(use,grade,basis,sources,label='evidence'): return dict(use=use,evidence_grade=grade,basis=basis,evidence_label=label,sources=sources)
def ema_trad(slug,use): return U(use,'traditional_only',"EMA HMPC: 'traditional use' (long-standing use) only.",['ema-'+slug])
def ema_area(slug,area): return U(f'EU herbal monograph adopted; therapeutic area: {area}','monograph_area_only','EMA page lists an adopted EU herbal monograph; no public summary text found.',['ema-'+slug])
plants=[]
def plant(id,common,botanical,uses,tox=None,look=None,cautions=None,extra=None):
    d=dict(id=id,common_name=common,botanical_name=botanical,medicinal_uses=uses)
    if tox: d['toxicity']=tox
    if look: d['lookalikes']=look
    if cautions: d['cautions']=cautions
    if extra: d.update(extra)
    plants.append(d)
def T(level,summary,sources): return dict(level=level,summary=summary,sources=sources)
def L(other,risk,how,sources,label='evidence'): return dict(lookalike=other,risk=risk,distinguishing_features=how,evidence_label=label,sources=sources)
